import{_ as p,r as n,o,c,e as a,a as i,s as l}from"./chunks/framework.CXcwiNg-.js";const v=JSON.parse('{"title":"|resize - October CMS - 3.x","titleTemplate":false,"description":"Twig Filter","frontmatter":{"subtitle":"Twig Filter"},"headers":[{"level":2,"title":"Custom Filenames","slug":"custom-filenames","link":"#custom-filenames","children":[]},{"level":2,"title":"Custom Folder Names","slug":"custom-folder-names","link":"#custom-folder-names","children":[]},{"level":2,"title":"Available Sources","slug":"available-sources","link":"#available-sources","children":[]},{"level":2,"title":"PHP Interface","slug":"php-interface","link":"#php-interface","children":[{"level":4,"title":"See Also","slug":"see-also","link":"#see-also","children":[]}]}],"relativePath":"3.x/markup/filter/resize.md","filePath":"3.x/markup/filter/resize.md"}'),u={name:"3.x/markup/filter/resize.md"};function r(k,s,g,d,m,h){const e=n("pre-heading"),t=n("post-heading");return o(),c("div",null,[a(e),s[0]||(s[0]=i("h1",null,"|resize",-1)),a(t),s[1]||(s[1]=l(`<p>The <code>|resize</code> filter attempts to resize the provided image source using the provided resizing configuration and outputs a URL to the resized image.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> <span class="token string"><span class="token punctuation">&#39;</span>image.jpg<span class="token punctuation">&#39;</span></span><span class="token operator">|</span>resize<span class="token punctuation">(</span><span class="token number">100</span><span class="token punctuation">,</span> <span class="token number">100</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">}}</span></span>
</code></pre></div><p>The filter accepts three arguments: <code>|resize(width, height, options)</code>.</p><p>If the filter can resize the provided image, then a URL to the image resizer (eg: <code>/resize/filename.png</code>) is returned. For subsequent requests, a direct URL to the resized image is returned. If the filter is unable to process the provided image, then it will instead return the original URL unmodified.</p><p>This will resize a banner.jpg media image to 1920 x 1080 ratio.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>img</span> <span class="token attr-name">src</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> <span class="token string"><span class="token punctuation">&#39;</span>banner.jpg<span class="token punctuation">&#39;</span></span><span class="token operator">|</span>media<span class="token operator">|</span>resize<span class="token punctuation">(</span><span class="token number">1920</span><span class="token punctuation">,</span> <span class="token number">1080</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">}}</span></span><span class="token punctuation">&quot;</span></span> <span class="token punctuation">/&gt;</span></span>
</code></pre></div><p>You can also pass a third options argument. This example will crop the image instead.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>img</span> <span class="token attr-name">src</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> <span class="token string"><span class="token punctuation">&#39;</span>banner.jpg<span class="token punctuation">&#39;</span></span><span class="token operator">|</span>resize<span class="token punctuation">(</span><span class="token number">800</span><span class="token punctuation">,</span> <span class="token number">600</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> mode<span class="token punctuation">:</span> <span class="token string"><span class="token punctuation">&#39;</span>crop<span class="token punctuation">&#39;</span></span> <span class="token punctuation">}</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">}}</span></span><span class="token punctuation">&quot;</span></span> <span class="token punctuation">/&gt;</span></span>
</code></pre></div><p>See the <a href="./../../extend/services/resizer.html">image resizer article</a> for more information on the available <code>options</code> parameters.</p><h2 id="custom-filenames"><a href="#custom-filenames" class="header-anchor">#</a> Custom Filenames</h2><p>The resizer will assign a random filename to resized images by default. You may use the original filename by passing the <code>true</code> to <code>filename</code> option to the resizer.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>img</span> <span class="token attr-name">src</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> <span class="token string"><span class="token punctuation">&#39;</span>banner.jpg<span class="token punctuation">&#39;</span></span><span class="token operator">|</span>resize<span class="token punctuation">(</span><span class="token number">800</span><span class="token punctuation">,</span> <span class="token number">600</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> filename<span class="token punctuation">:</span> <span class="token boolean">true</span> <span class="token punctuation">}</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">}}</span></span><span class="token punctuation">&quot;</span></span> <span class="token punctuation">/&gt;</span></span>
</code></pre></div><p>The <code>filename</code> option also supports a custom filename as a string. The filename should not contain an extension since the original one is used.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>img</span> <span class="token attr-name">src</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> <span class="token string"><span class="token punctuation">&#39;</span>banner.jpg<span class="token punctuation">&#39;</span></span><span class="token operator">|</span>resize<span class="token punctuation">(</span><span class="token number">800</span><span class="token punctuation">,</span> <span class="token number">600</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> filename<span class="token punctuation">:</span> <span class="token string"><span class="token punctuation">&#39;</span>my-seo-friendly-name<span class="token punctuation">&#39;</span></span> <span class="token punctuation">}</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">}}</span></span><span class="token punctuation">&quot;</span></span> <span class="token punctuation">/&gt;</span></span>
</code></pre></div><p>You may modify the extension with the <code>extension</code> option. This process will attempt to convert from one file type to another, for example, converting a JPG to a PNG file.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>img</span> <span class="token attr-name">src</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> <span class="token string"><span class="token punctuation">&#39;</span>banner.jpg<span class="token punctuation">&#39;</span></span><span class="token operator">|</span>resize<span class="token punctuation">(</span><span class="token number">800</span><span class="token punctuation">,</span> <span class="token number">600</span><span class="token punctuation">,</span> <span class="token punctuation">{</span>
    filename<span class="token punctuation">:</span> <span class="token string"><span class="token punctuation">&#39;</span>my-seo-friendly-name<span class="token punctuation">&#39;</span></span><span class="token punctuation">,</span>
    extension<span class="token punctuation">:</span> <span class="token string"><span class="token punctuation">&#39;</span>png<span class="token punctuation">&#39;</span></span>
<span class="token punctuation">}</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">}}</span></span><span class="token punctuation">&quot;</span></span> <span class="token punctuation">/&gt;</span></span>
</code></pre></div><h2 id="custom-folder-names"><a href="#custom-folder-names" class="header-anchor">#</a> Custom Folder Names</h2><p>When using custom filenames, the filename will still contain a trailing hash to ensure uniqueness within the resizer resource directory. In most cases this is enough to satisfy basic SEO requirements. For example, the file will appear in the system like so.</p><ul><li><code>.../800_600_0_0_auto/my-seo-friendly-name_001a14981ffe90700046616c5f415467.png</code></li></ul><p>A <code>group</code> can be specified as a folder name, this will place the image in a dedicated resource group.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>img</span> <span class="token attr-name">src</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> <span class="token string"><span class="token punctuation">&#39;</span>banner.jpg<span class="token punctuation">&#39;</span></span><span class="token operator">|</span>resize<span class="token punctuation">(</span><span class="token number">800</span><span class="token punctuation">,</span> <span class="token number">600</span><span class="token punctuation">,</span> <span class="token punctuation">{</span>
    filename<span class="token punctuation">:</span> <span class="token string"><span class="token punctuation">&#39;</span>my-seo-friendly-name<span class="token punctuation">&#39;</span></span><span class="token punctuation">,</span>
    group<span class="token punctuation">:</span> <span class="token string"><span class="token punctuation">&#39;</span>2024-banners<span class="token punctuation">&#39;</span></span>
<span class="token punctuation">}</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">}}</span></span><span class="token punctuation">&quot;</span></span> <span class="token punctuation">/&gt;</span></span>
</code></pre></div><p>For example, the above will place the file in the following directory:</p><ul><li><code>.../800_600_0_0_auto/2024-banners/my-seo-friendly-name.png</code></li></ul><p>However, keep in mind, this approach can be prone to naming collisions. If a different file is resized using the same name and resize options, it will output the original file since there is no unique hash added to the path.</p><h2 id="available-sources"><a href="#available-sources" class="header-anchor">#</a> Available Sources</h2><p>You may reference images from multiple sources, including the following paths:</p><ul><li><code>/app</code></li><li><code>/plugins</code></li><li><code>/themes</code></li><li><code>/modules</code></li><li><code>/storage/app/uploads</code></li><li><code>/storage/app/media</code></li></ul><p>For example:</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> <span class="token string"><span class="token punctuation">&#39;</span>/plugins/acme/blog/assets/images/someimage.png<span class="token punctuation">&#39;</span></span><span class="token operator">|</span>resize<span class="token punctuation">(</span><span class="token punctuation">.</span><span class="token punctuation">.</span><span class="token punctuation">.</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">}}</span></span>
</code></pre></div><h2 id="php-interface"><a href="#php-interface" class="header-anchor">#</a> PHP Interface</h2><p>You may resize images in PHP using the <code>System\\Classes\\ResizeImages</code> and <code>resize</code> method. The return value is a URL location to the resized image.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">ResizeImages</span><span class="token operator">::</span><span class="token function">resize</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;path/to/asset.jpg&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>The method accepts a width (second argument), height (third argument) and <a href="./../../extend/services/resizer.html">resizer options</a> (fourth argument).</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">ResizeImages</span><span class="token operator">::</span><span class="token function">resize</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;path/to/asset.jpg&#39;</span><span class="token punctuation">,</span> <span class="token number">800</span><span class="token punctuation">,</span> <span class="token number">600</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;mode&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;crop&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="see-also"><a href="#see-also" class="header-anchor">#</a> See Also</h4><div class="custom-block also"><ul><li><a href="./../../extend/services/resizer.html">Resizer Service</a></li></ul></div>`,36))])}const w=p(u,[["render",r]]);export{v as __pageData,w as default};
